<?php
/**
 * Generated by nothing: this file is static and reads its configuration from
 * the environment set by the presso engine. Do not edit inside a container.
 *
 * It is baked into the image, root-owned and read-only. The PRESSO_* variable
 * names below are the env contract between the engine and every runtime
 * flavor (FrankenPHP and nginx + PHP-FPM). RUNTIME.md sections 7 and 8
 * explain the individual constants.
 */

/**
 * Read one environment variable, treating unset and empty alike.
 */
function presso_env( string $name, ?string $default = null ): ?string {
	$value = getenv( $name );
	if ( $value === false || $value === '' ) {
		return $default;
	}
	return $value;
}

// --- Database ---------------------------------------------------------------
// Charset, collation and prefix are preserved from the source site on
// migration and never silently converted.
define( 'DB_NAME', presso_env( 'PRESSO_DB_NAME', '' ) );
define( 'DB_USER', presso_env( 'PRESSO_DB_USER', '' ) );
define( 'DB_PASSWORD', presso_env( 'PRESSO_DB_PASSWORD', '' ) );
define( 'DB_HOST', presso_env( 'PRESSO_DB_HOST', 'presso-mariadb' ) );
define( 'DB_CHARSET', presso_env( 'PRESSO_DB_CHARSET', 'utf8mb4' ) );
define( 'DB_COLLATE', presso_env( 'PRESSO_DB_COLLATE', '' ) );

$table_prefix = presso_env( 'PRESSO_DB_PREFIX', 'wp_' );

// --- Salts -------------------------------------------------------------------
// Minted once per site by the engine; rotating them logs everyone out.
foreach ( array(
	'AUTH_KEY',
	'SECURE_AUTH_KEY',
	'LOGGED_IN_KEY',
	'NONCE_KEY',
	'AUTH_SALT',
	'SECURE_AUTH_SALT',
	'LOGGED_IN_SALT',
	'NONCE_SALT',
) as $presso_salt ) {
	define( $presso_salt, presso_env( 'PRESSO_SALT_' . $presso_salt, '' ) );
}
unset( $presso_salt );

// --- Scheme ------------------------------------------------------------------
// TLS terminates at the shared edge and the container only ever sees plain
// HTTP, so is_ssl() would be false on https sites and wp-login would redirect
// in a loop. Only the edge reaches :8080, so the header can be trusted.
if ( isset( $_SERVER['HTTP_X_FORWARDED_PROTO'] ) && $_SERVER['HTTP_X_FORWARDED_PROTO'] === 'https' ) {
	$_SERVER['HTTPS'] = 'on';
}

// --- URLs --------------------------------------------------------------------
// The engine's primary domain is authoritative; the siteurl/home options in
// the database are not used for routing. The engine always sets this; the
// fallback to database values only exists so a misconfigured container fails
// loudly in the logs instead of fatally.
$presso_site_url = presso_env( 'PRESSO_SITE_URL' );
if ( $presso_site_url !== null ) {
	$presso_site_url = rtrim( $presso_site_url, '/' );
	define( 'WP_HOME', $presso_site_url );
	define( 'WP_SITEURL', $presso_site_url );
} else {
	error_log( '{"presso":"config_warning","msg":"PRESSO_SITE_URL is not set; WP_HOME/WP_SITEURL fall back to the database"}' );
}
unset( $presso_site_url );

// --- Profile -----------------------------------------------------------------
// prod (default) or dev; the same image serves both (RUNTIME.md, "Goal").
$presso_profile = presso_env( 'PRESSO_PROFILE', 'prod' );
define( 'WP_ENVIRONMENT_TYPE', $presso_profile === 'dev' ? 'development' : 'production' );

if ( $presso_profile === 'dev' ) {
	define( 'WP_DEBUG', true );
	// No debug.log: wp-content/ is not writable by the web user, and a file
	// path would also bypass the container log. With WP_DEBUG_LOG false and
	// log_errors on (php/presso.ini), notices go to stderr via the SAPI like
	// every other log line of this container.
	define( 'WP_DEBUG_LOG', false );
	define( 'WP_DEBUG_DISPLAY', false );
	define( 'SCRIPT_DEBUG', true );
} else {
	define( 'WP_DEBUG', false );
	define( 'WP_DEBUG_DISPLAY', false );
}
// Never render errors into a response, whatever a plugin tries.
ini_set( 'display_errors', '0' );
unset( $presso_profile );

// --- Runtime policy (RUNTIME.md section 7) -----------------------------------
define( 'DISABLE_WP_CRON', true ); // Real cron runs WP-CLI from the engine.
define( 'WP_POST_REVISIONS', (int) presso_env( 'PRESSO_WP_POST_REVISIONS', '10' ) );
define( 'AUTOSAVE_INTERVAL', (int) presso_env( 'PRESSO_WP_AUTOSAVE_INTERVAL', '120' ) );
define( 'DISALLOW_FILE_EDIT', true ); // In-admin code editor, off in both modes.
define( 'WP_AUTO_UPDATE_CORE', false ); // The image owns core.
define( 'AUTOMATIC_UPDATER_DISABLED', true );
define( 'WP_MEMORY_LIMIT', presso_env( 'PRESSO_WP_MEMORY_LIMIT', '256M' ) );
define( 'WP_MAX_MEMORY_LIMIT', presso_env( 'PRESSO_WP_MAX_MEMORY_LIMIT', '512M' ) );
define( 'FS_METHOD', 'direct' );

// File modification policy (RUNTIME.md section 8): LOCKED by default, OPEN
// per site. Locked applies to web requests only; WP-CLI (driven by the
// engine) must still be able to install and update plugins and themes.
if ( presso_env( 'PRESSO_FILE_MODS', 'locked' ) === 'locked' && PHP_SAPI !== 'cli' ) {
	define( 'DISALLOW_FILE_MODS', true );
}

// The system plugin lives in the image, outside the volume (section 14).
// Its assets are not served; the URL only has to be well-formed.
define( 'WPMU_PLUGIN_DIR', '/opt/presso/mu-plugins' );
define( 'WPMU_PLUGIN_URL', ( defined( 'WP_SITEURL' ) ? WP_SITEURL : '' ) . '/-/mu-plugins' );

// --- Object cache (RUNTIME.md section 5) -------------------------------------
// The Redis Object Cache drop-in is copied into wp-content by the entrypoint
// when PRESSO_REDIS_HOST is set. The server is Valkey; WP_REDIS_* and
// PRESSO_REDIS_* name the compatible Redis protocol. One ACL user per site.
define( 'WP_CACHE', true );
$presso_redis_host = presso_env( 'PRESSO_REDIS_HOST' );
if ( $presso_redis_host !== null ) {
	define( 'WP_REDIS_HOST', $presso_redis_host );
	define( 'WP_REDIS_PORT', (int) presso_env( 'PRESSO_REDIS_PORT', '6379' ) );
	// Valkey ACL credentials. The drop-in's phpredis path only performs ACL
	// authentication when WP_REDIS_PASSWORD is the [username, password] array
	// form (WP_REDIS_USERNAME is honoured by the Predis client alone).
	if ( presso_env( 'PRESSO_REDIS_PASSWORD' ) !== null ) {
		if ( presso_env( 'PRESSO_REDIS_USER' ) !== null ) {
			define( 'WP_REDIS_USERNAME', presso_env( 'PRESSO_REDIS_USER' ) );
			define( 'WP_REDIS_PASSWORD', array( presso_env( 'PRESSO_REDIS_USER' ), presso_env( 'PRESSO_REDIS_PASSWORD' ) ) );
		} else {
			define( 'WP_REDIS_PASSWORD', presso_env( 'PRESSO_REDIS_PASSWORD' ) );
		}
	}
	if ( presso_env( 'PRESSO_REDIS_PREFIX' ) !== null ) {
		define( 'WP_REDIS_PREFIX', presso_env( 'PRESSO_REDIS_PREFIX' ) );
	}
	define( 'WP_REDIS_SELECTIVE_FLUSH', true ); // Flush only this site's prefix.
	define( 'WP_REDIS_MAXTTL', 86400 ); // Bound keys so volatile-lru can evict.
	define( 'WP_REDIS_DISABLE_BANNERS', true );
	define( 'WP_REDIS_DISABLE_METRICS', true );
	define( 'WP_REDIS_GRACEFUL', true ); // Cache outage degrades, never fatals.
} else {
	define( 'WP_REDIS_DISABLED', true );
}
unset( $presso_redis_host );

// --- System plugin passthrough (RUNTIME.md section 14) -----------------------
// Convenience constants for non-secret values. PRESSO_PURGE_TOKEN and
// PRESSO_LOGIN_SECRET are deliberately NOT defined: the plugin reads them
// with getenv() so they never show up in `wp config list`.
define( 'PRESSO_SITE_ID', presso_env( 'PRESSO_SITE_ID', '' ) );
define( 'PRESSO_ENGINE_URL', rtrim( presso_env( 'PRESSO_ENGINE_URL', '' ), '/' ) );
define( 'PRESSO_CACHE', presso_env( 'PRESSO_CACHE', 'on' ) );
define( 'PRESSO_CACHE_TTL', (int) presso_env( 'PRESSO_CACHE_TTL', '43200' ) );
define( 'PRESSO_CACHE_SWR', presso_env( 'PRESSO_CACHE_SWR', 'off' ) );
define( 'PRESSO_TELEMETRY_SAMPLE', (float) presso_env( 'PRESSO_TELEMETRY_SAMPLE', '0.1' ) );

// --- Bootstrap ---------------------------------------------------------------
if ( ! defined( 'ABSPATH' ) ) {
	define( 'ABSPATH', __DIR__ . '/' );
}
require_once ABSPATH . 'wp-settings.php';
